// The registry disagrees with what it was sent: send it again.
// The correction is due from the day it is found.
func (q *Queries) Reregister(ctx context.Context, arg ReregisterParams) error {
	_, err := q.db.Exec(ctx, reregister, arg.Today, arg.ID)
	return err
}

const resolveDivergences = `-- name: ResolveDivergences :exec
UPDATE receivables.divergences SET resolved_at = $1
WHERE livemode = $2 AND kind = $3 AND resolved_at IS NULL AND NOT (subject = ANY($4::text[]))
`

type ResolveDivergencesParams struct {
	Now      pgtype.Timestamptz
	Livemode bool
	Kind     string
	Still    []string
}

// Those of a kind a reconciliation no longer found.
func (q *Queries) ResolveDivergences(ctx context.Context, arg ResolveDivergencesParams) error {
	_, err := q.db.Exec(ctx, resolveDivergences,
		arg.Now,
		arg.Livemode,
		arg.Kind,
		arg.Still,
	)
	return err
}

const setOptIn = `-- name: SetOptIn :exec
INSERT INTO receivables.opt_ins (merchant_id, livemode, financier, active, synced, updated_at)
VALUES ($1, $2, $3, $4, false, $5)
ON CONFLICT (merchant_id, livemode, financier) DO UPDATE
SET active = excluded.active, synced = false, sync_error = '', retry_at = NULL, updated_at = excluded.updated_at
`

type SetOptInParams struct {
	MerchantID string
	Livemode   bool
	Financier  string
	Active     bool
	Now        pgtype.Timestamptz
}

func (q *Queries) SetOptIn(ctx context.Context, arg SetOptInParams) error {
	_, err := q.db.Exec(ctx, setOptIn,
		arg.MerchantID,
		arg.Livemode,
		arg.Financier,
		arg.Active,
		arg.Now,
	)
	return err
}

const unitsToReconcile = `-- name: UnitsToReconcile :many
SELECT id, merchant_id, livemode, arrangement, settlement_date, value, blocked, currency, constituted_on, version, registered_version, registered_at, register_error, register_retry_at, settled_on, settled_amount, payments, created_at, updated_at FROM receivables.units
WHERE livemode = $1 AND (settled_on IS NULL OR settlement_date >= $2)
ORDER BY settlement_date, id
`

type UnitsToReconcileParams struct {
	Livemode bool
	Since    pgtype.Date
}

// A mode's units still unsettled, or settled on or after since.
func (q *Queries) UnitsToReconcile(ctx context.Context, arg UnitsToReconcileParams) ([]ReceivablesUnit, error) {
	rows, err := q.db.Query(ctx, unitsToReconcile, arg.Livemode, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReceivablesUnit{}
	for rows.Next() {
		var i ReceivablesUnit
		if err := rows.Scan(
			&i.ID,
			&i.MerchantID,
			&i.Livemode,
			&i.Arrangement,
			&i.SettlementDate,
			&i.Value,
			&i.Blocked,
			&i.Currency,
			&i.ConstitutedOn,
			&i.Version,
			&i.RegisteredVersion,
			&i.RegisteredAt,
			&i.RegisterError,
			&i.RegisterRetryAt,
			&i.SettledOn,
			&i.SettledAmount,
			&i.Payments,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

