const unregisteredSince = `-- name: UnregisteredSince :many
SELECT id, livemode, constituted_on, register_error FROM receivables.units
WHERE version > registered_version AND constituted_on <= $1 AND livemode = ANY($2::boolean[])
ORDER BY constituted_on, id
LIMIT 1000
`

type UnregisteredSinceParams struct {
	Day   pgtype.Date
	Modes []bool
}

type UnregisteredSinceRow struct {
	ID            string
	Livemode      bool
	ConstitutedOn pgtype.Date
	RegisterError string
}

// Units not registered as they are, from sales on or before a day: the late ones.
func (q *Queries) UnregisteredSince(ctx context.Context, arg UnregisteredSinceParams) ([]UnregisteredSinceRow, error) {
	rows, err := q.db.Query(ctx, unregisteredSince, arg.Day, arg.Modes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UnregisteredSinceRow{}
	for rows.Next() {
		var i UnregisteredSinceRow
		if err := rows.Scan(
			&i.ID,
			&i.Livemode,
			&i.ConstitutedOn,
			&i.RegisterError,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
